106: /**
107:  * Constructs a 64 bit two's-complement integer, given its low and high 32 bit values as *signed* integers.
108:  *  See the from* functions below for more convenient ways of constructing Longs.
109:  * @exports Long
110:  * @class A Long class for representing a 64 bit two's-complement integer value.
111:  * @param {number} low The low (signed) 32 bits of the long
112:  * @param {number} high The high (signed) 32 bits of the long
113:  * @param {boolean=} unsigned Whether unsigned or not, defaults to signed
114:  * @constructor
115:  */
116: function Long(low, high, unsigned) {
117:   /**
118:    * The low 32 bits as a signed value.
119:    * @type {number}
120:    */
121:   this.low = low | 0;
122: 
123:   /**
124:    * The high 32 bits as a signed value.
125:    * @type {number}
126:    */
127:   this.high = high | 0;
128: 
129:   /**
130:    * Whether unsigned or not.
131:    * @type {boolean}
132:    */
133:   this.unsigned = !!unsigned;
134: }
