212: function fromInt(value, unsigned) {
213:   var obj, cachedObj, cache;
214:   if (unsigned) {
215:     value >>>= 0;
216:     if ((cache = 0 <= value && value < 256)) {
217:       cachedObj = UINT_CACHE[value];
218:       if (cachedObj) return cachedObj;
219:     }
220:     obj = fromBits(value, 0, true);
221:     if (cache) UINT_CACHE[value] = obj;
222:     return obj;
223:   } else {
224:     value |= 0;
225:     if ((cache = -128 <= value && value < 128)) {
226:       cachedObj = INT_CACHE[value];
227:       if (cachedObj) return cachedObj;
228:     }
229:     obj = fromBits(value, value < 0 ? -1 : 0, false);
230:     if (cache) INT_CACHE[value] = obj;
