251:   if (isNaN(value)) return unsigned ? UZERO : ZERO;
252:   if (unsigned) {
253:     if (value < 0) return UZERO;
254:     if (value >= TWO_PWR_64_DBL) return MAX_UNSIGNED_VALUE;
255:   } else {
256:     if (value <= -TWO_PWR_63_DBL) return MIN_VALUE;
257:     if (value + 1 >= TWO_PWR_63_DBL) return MAX_VALUE;
258:   }
259:   if (value < 0) return fromNumber(-value, unsigned).neg();
260:   return fromBits(
261:     value % TWO_PWR_32_DBL | 0,
262:     (value / TWO_PWR_32_DBL) | 0,
263:     unsigned,
264:   );
