316:   if (typeof unsigned === "number") {
317:     // For goog.math.long compatibility
318:     radix = unsigned;
319:     unsigned = false;
320:   } else {
321:     unsigned = !!unsigned;
322:   }
323:   if (
324:     str === "NaN" ||
325:     str === "Infinity" ||
326:     str === "+Infinity" ||
